/* @lc app=leetcode id=3615 lang=kotlin */ class Solution { fun run(g: Map<Int, List<Int>>, n: Int, label: String, vis: BooleanArray, seed: List<Int>, st: Int): Int = if (seed.isEmpty()) 0 else generateSequence(seed to st) { (f, L) -> f.flatMap { s -> (s % n).let { v -> (s / n % n).let { u -> (s / n / n).let { mask -> g[u].orEmpty().filter { mask shr it and 1 == 0 }.flatMap { a -> g[v].orEmpty().filter { b -> b != a && mask shr b and 1 == 0 && label[a] == label[b] }.map { b -> ((mask or (1 shl a) or (1 shl b)) * n + a) * n + b } } } } } }.filter { !vis[it] && true.also { _ -> vis[it] = true } }.takeIf { it.isNotEmpty() }?.let { it to L + 2 } }.last().second fun maxLen(n: Int, edges: Array<IntArray>, label: String): Int = edges.flatMap { (a, b) -> listOf(a to b, b to a) }.groupBy({ it.first }, { it.second }).let { g -> BooleanArray(n * n * (1 shl n)).let { vis -> maxOf(run(g, n, label, vis, (0 until n).map { ((1 shl it) * n + it) * n + it }.onEach { vis[it] = true }, 1), run(g, n, label, vis, edges.flatMap { (a, b) -> listOf(a to b, b to a) }.filter { (a, b) -> label[a] == label[b] }.map { (a, b) -> (((1 shl a) or (1 shl b)) * n + a) * n + b }.distinct().onEach { vis[it] = true }, 2)) } } }